class Solution {
  public long[] minTimeMaxPower(
      int n, int[][] edges, int power, int[] cost, int source, int target) {
    int[] head = new int[n], next = new int[edges.length];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < edges.length; i++) {
      next[i] = head[edges[i][0]];
      head[edges[i][0]] = i;
    }
    long INF = Long.MAX_VALUE / 4;
    long[] dist = new long[n * (power + 1)];
    java.util.Arrays.fill(dist, INF);
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    dist[source * (power + 1) + power] = 0;
    pq.add(new long[] {0, (long) source * (power + 1) + power});
    long bestTime = INF;
    int bestPower = -1;
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int state = (int) top[1];
      if (top[0] > dist[state]) continue;
      if (top[0] > bestTime) break;
      int u = state / (power + 1), p = state % (power + 1);
      if (u == target) {
        if (top[0] < bestTime) {
          bestTime = top[0];
          bestPower = p;
        } else if (top[0] == bestTime) bestPower = Math.max(bestPower, p);
      }
      if (p < cost[u]) continue;
      int np = p - cost[u];
      for (int e = head[u]; e >= 0; e = next[e]) {
        int v = edges[e][1];
        long nd = top[0] + edges[e][2];
        int ns = v * (power + 1) + np;
        if (nd < dist[ns]) {
          dist[ns] = nd;
          pq.add(new long[] {nd, ns});
        }
      }
    }
    if (bestPower < 0) return new long[] {-1, -1};
    return new long[] {bestTime, bestPower};
  }
}
